#ifndef FPTZ_GEOMETRY_H
#define FPTZ_GEOMETRY_H
/* Two full square sources; never crop or resize either lens. */
#define FPTZ_SOURCE_WIDTH 1328u
#define FPTZ_SOURCE_HEIGHT 1328u
#define FPTZ_SOURCE_PIXELS (FPTZ_SOURCE_WIDTH * FPTZ_SOURCE_HEIGHT)
#define FPTZ_SOURCE_RGBX_BYTES (FPTZ_SOURCE_PIXELS * 4u)
#define FPTZ_OUTPUT_WIDTH 2656u
#define FPTZ_OUTPUT_HEIGHT 1328u
#define FPTZ_OUTPUT_PIXELS (FPTZ_OUTPUT_WIDTH * FPTZ_OUTPUT_HEIGHT)
#define FPTZ_OUTPUT_RGBX_BYTES (FPTZ_OUTPUT_PIXELS * 4u)
#define FPTZ_LUT_PLANE_BYTES (FPTZ_OUTPUT_PIXELS * 4u)
#define FPTZ_LUT_WEIGHT_BYTES (FPTZ_OUTPUT_PIXELS * 2u)
#define FPTZ_LUT_XF_OFFSET 0u
#define FPTZ_LUT_YF_OFFSET FPTZ_LUT_PLANE_BYTES
#define FPTZ_LUT_XR_OFFSET (FPTZ_LUT_PLANE_BYTES * 2u)
#define FPTZ_LUT_YR_OFFSET (FPTZ_LUT_PLANE_BYTES * 3u)
#define FPTZ_LUT_W_OFFSET (FPTZ_LUT_PLANE_BYTES * 4u)
#define FPTZ_LUT_BYTES (FPTZ_LUT_W_OFFSET + FPTZ_LUT_WEIGHT_BYTES)
#define FPTZ_PL_CENTER_X 1328u
#define FPTZ_PL_CENTER_Y 664u
#define FPTZ_CACHE_ROWS 384u
#define FPTZ_PTZ_HFOV_MDEG 90000u
#define FPTZ_PANORAMA_HFOV_MDEG 360000u
#define FPTZ_PANORAMA_CAPABILITY 1u
#define FPTZ_PTZ_GRID_MDEG 100
#define FPTZ_PTZ_PAN_PERIOD_MDEG 360000
#define FPTZ_PTZ_TILT_LIMIT_MDEG 90000
#define FPTZ_Q6_X_LIMIT ((FPTZ_SOURCE_WIDTH - 1u) * 64u)
#define FPTZ_Q6_Y_LIMIT ((FPTZ_SOURCE_HEIGHT - 1u) * 64u)
#define FPTZ_LENS_FRONT 0u
#define FPTZ_LENS_REAR 1u
#define FPTZ_LENS_COUNT 2u
#define FPTZ_PL_ABI_VERSION 4u
#define FPTZ_PL_LUT_FORMAT 1u
#define FPTZ_PL_CACHE_MODE 1u
#define FPTZ_PL_SOURCE_SIZE ((FPTZ_SOURCE_HEIGHT << 16) | FPTZ_SOURCE_WIDTH)
#define FPTZ_PL_OUTPUT_SIZE ((FPTZ_OUTPUT_HEIGHT << 16) | FPTZ_OUTPUT_WIDTH)
/* PS-2: only validated paired JPEG objects can enter the dual scheduler. */
#define FPTZ_DUAL_MEDIA_READY 1u
#endif
